using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class Sync216Tests {
 static int n;static void Check(bool v,string s){if(!v)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
 sealed class Voice:KokoroEngine {public override void CheckFiles(){}public override Wave Generate(string text,double speed,string p){return new Wave{Rate=24000,Samples=Enumerable.Range(0,55200).Select(i=>(short)(5000*Math.Cos(i*.061))).ToArray()};}}
 sealed class Translator:ITextRewriter {public bool Fail,BadSubject,NoGenerate;public string Rewrite(string p,Func<bool> c,Action<string> a){if(NoGenerate&&!p.StartsWith("TASK=TRANSLATION_VERIFY"))throw new IOException("unexpected generation for a matching source translation");if(Fail)throw new IOException("fixture translation inference error");if(BadSubject&&p.StartsWith("TASK=TRANSLATION_VERIFY"))return "{\"items\":[{\"id\":1,\"ok\":true,\"source_subject_type\":\"food\",\"target_subject_type\":\"place\",\"reason\":\"fixture mismatch\"}]}";return p.StartsWith("TASK=TRANSLATION_VERIFY")?"{\"items\":[{\"id\":1,\"ok\":true,\"reason\":\"fixture\"}]}":"{\"cues\":[{\"id\":1,\"text\":\"John đã mua hai quả táo.\"}]}";}}
 public static int Main(){try{string root=Path.Combine(Path.GetTempPath(),"sync216 "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var cues=new List<Cue>{new Cue{Id=1,Start=0,End=2.4,Text="John bought two apples."}};string src=Path.Combine(root,"story.srt");File.WriteAllText(src,Scripts.ToSrt(cues));string original=StateFiles.Hash(src);
  var o=new RenderOptions{Anchored=true,Locked=false,Breathing=BreathMode.None,NormalizeLoudness=false,CheckpointRoot=Path.Combine(root,"pcm"),TranslationCacheRoot=Path.Combine(root,"translation"),Translator=new Translator(),ReportContext=new VoiceReportContext{SourcePath=src,SourceCues=cues}};string wav;using(var e=new Voice{Root=root,VoiceName="fixture"})wav=Renderer.Render(cues,e,o,Path.Combine(root,"story.wav"),(p,m)=>{});string stem=Path.ChangeExtension(wav,null);
  Check(o.Translation.Complete&&o.Translation.Text.Count==1,"Complete translation status requires all final cue IDs");
  Check(new[]{".wav",".final.srt",".final.vi.txt",".ai-repair-report.txt",".voice-report.txt"}.All(ext=>File.Exists(stem+ext)),"Publish all five synchronized outputs using a single basename");
  var srt=Scripts.ParseSrt(File.ReadAllText(stem+".final.srt"));var vi=File.ReadAllText(stem+".final.vi.txt");Check(srt[0].Text==o.RunReport.Units.Single().Text&&vi.Contains("EN: "+srt[0].Text)&&vi.Contains("VI: John đã mua hai quả táo."),"Actual TTS request, final SRT and bilingual EN are exact; VI contains the full checked translation");
  Check(!vi.Contains("[CHƯA DỊCH]")&&!vi.Contains("[TRANSLATION_INCOMPLETE]")&&vi.Contains("00:00:02,400"),"Successful bilingual export contains real Vietnamese, cue number and source timecode");Check(StateFiles.Hash(src)==original&&FinalAudio.PcmFrames(wav)==57600,"Source bytes and exact timeline duration remain protected");
  ((Translator)o.Translator).Fail=true;o.TranslationCacheRoot=Path.Combine(root,"broken-translation");string again;using(var e=new Voice{Root=root,VoiceName="fixture"})again=Renderer.Render(cues,e,o,Path.Combine(root,"story.wav"),(p,m)=>{});string failedStem=Path.ChangeExtension(again,null);
  Check(File.Exists(again)&&again!=wav&&!o.Translation.Complete&&o.RunReport.Outcome.StartsWith("TRANSLATION_INCOMPLETE"),"Translation failure preserves verified WAV work with an explicit incomplete set status");
  Check(File.ReadAllText(failedStem+".ai-repair-report.txt").Contains("Trạng thái bộ đầu ra: TRANSLATION_INCOMPLETE")&&File.ReadAllText(failedStem+".voice-report.txt").Contains("fixture translation inference error"),"Both reports separate WAV verification from translation failure and retain the useful error");
  Check(o.RunReport.Units.All(u=>u.CacheCalls>0),"Retry after translation failure reuses completed PCM stage without TTS");
  var ab=RepairSession.Open(src,cues,root,false);ab.Settings=new VoiceSettings{Mode=0,Normalize=false,Breathing=(int)BreathMode.None,Slow=true,MinSpeed=.9,MaxSpeed=1.25}.Xml().ToString();var abWords=VoiceRenderReport.Snapshot(cues);abWords[0].Text="John purchased two apples.";var abOptions=AudioRepair.Options(ab.Settings);abOptions.Translator=new Translator();abOptions.TranslationCacheRoot=Path.Combine(root,"ab-translation");string abWav;using(var e=new Voice{Root=root,VoiceName="fixture"}){var take=AudioRepair.Trial(ab,ab.Parts[0],e,abOptions,"fixture",abWords,"A");if(!take.Success)throw new Exception("A/B fixture did not fit: "+take.Reason);ab.Parts[0].Selected=take;abWav=AudioRepair.Merge(ab,e,abOptions,(i,m)=>{});}string abStem=Path.ChangeExtension(abWav,null);Check(abOptions.Translation.Complete&&new[]{".wav",".final.srt",".final.vi.txt",".ai-repair-report.txt",".voice-report.txt"}.All(ext=>File.Exists(abStem+ext)),"Legacy A/B adoption publishes all five files through the same atomic synchronization path");Check(Scripts.ParseSrt(File.ReadAllText(abStem+".final.srt"))[0].Text==abWords[0].Text&&File.ReadAllText(abStem+".final.vi.txt").Contains("EN: "+abWords[0].Text)&&ab.PublishedCues[0].Text==abWords[0].Text&&StateFiles.Hash(src)==original,"A/B final SRT and bilingual EN use the actual adopted take instead of old source wording");abOptions.Translator=new Translator{Fail=true};abOptions.TranslationCacheRoot=Path.Combine(root,"ab-translation-failure");using(var e=new Voice{Root=root,VoiceName="fixture"})abWav=AudioRepair.Merge(ab,e,abOptions,(i,m)=>{});Check(!abOptions.Translation.Complete&&File.ReadAllText(Path.ChangeExtension(abWav,null)+".voice-report.txt").Contains("TRANSLATION_INCOMPLETE"),"A/B translation failure also preserves verified PCM with a visibly incomplete output set");
  var shortCues=VoiceRenderReport.Snapshot(cues);shortCues[0].End=3.1;string shortSource=Path.Combine(root,"short-stage.srt");File.WriteAllText(shortSource,Scripts.ToSrt(shortCues));var shortAb=RepairSession.Open(shortSource,shortCues,root,true);var shortSettings=new VoiceSettings{Mode=2,Normalize=false,Breathing=(int)BreathMode.None,MinSpeed=.9,MaxSpeed=1.25};shortAb.Settings=shortSettings.Xml().ToString();using(var e=new Voice{Root=root,VoiceName="fixture"}){var shortTake=AudioRepair.Trial(shortAb,shortAb.Parts[0],e,AudioRepair.Options(shortAb.Settings),"fixture",shortCues,"A");Check(!shortTake.Success&&Wave.Read(shortTake.Audio).Duration<3.1,"A/B V15.6 cannot pad the stage tail and pretend the measured shortage was repaired");shortTake.Success=true;shortTake.Reason="Nghỉ đệm cuối 0.55s; legacy fixture";shortAb.Parts[0].Selected=shortTake;bool oldPadding=false;try{AudioRepair.Merge(shortAb,e,AudioRepair.Options(shortAb.Settings),(i,m)=>{});}catch(Exception ex){oldPadding=ex.Message.Contains("NEEDS_REVIEW");}Check(oldPadding&&shortAb.Output.Length==0,"Legacy accepted A/B stage with artificial tail must be remeasured instead of silently imported as PASS");}
  foreach(var item in new[]{new[]{"He paid three hundred thirty-two dollars.","Anh ấy trả ba trăm ba mươi hai đô la."},new[]{"He paid twelve hundred dollars.","Anh ấy trả một nghìn hai trăm đô la."},new[]{"He bought a six-foot log.","Anh ấy mua một khúc dài sáu foot."},new[]{"They started with an American tray priced at two fifty.","Họ bắt đầu với khay Mỹ giá hai đô la năm mươi xu."},new[]{"The price was two fifty.","Giá là hai đô la rưỡi."}}){OfflineTranslation.Validate(item[0],item[1]);Check(true,"Vietnamese number validation supports actual compound quantity: "+item[0]);}
  Check(OfflineTranslation.NormalizeEnglishPrefix("Soon the dining table disappeared.","Soon, bàn ăn biến mất.")=="Chẳng mấy chốc, bàn ăn biến mất."&&OfflineTranslation.NormalizeEnglishPrefix("Soon Lee went home.","Soon Lee đã về nhà.")=="Soon Lee đã về nhà.","Normalize an untranslated sentence adverb in subject context while preserving a similarly spelled proper name");
  var subjects=OfflineTranslation.Run(cues,new Translator{BadSubject=true},Path.Combine(root,"bad-subject"),()=>false,(i,m)=>{});Check(!subjects.Complete&&subjects.Status=="TRANSLATION_INCOMPLETE","Structured food/place subject mismatch overrides an inconsistent model ok=true and never silently passes translation");
  bool shops=false;try{OfflineTranslation.Validate("Store sandwiches often have few vegetables.","Các cửa hàng bán bánh mì thường có ít rau.");}catch{shops=true;}Check(shops&&OfflineTranslation.TranslationInput("Store sandwiches often have few vegetables.").StartsWith("sandwiches sold in stores")&&OfflineTranslation.TranslationInput("Store sandwiches in the fridge.")=="Store sandwiches in the fridge.","Food noun compound is clarified only for translation and cannot be silently changed into retail-shop subject or an imperative");
  string pairedSource=Path.Combine(root,"paired.srt");File.WriteAllText(pairedSource,Scripts.ToSrt(cues));File.WriteAllText(Path.Combine(root,"paired_Tieng_Viet.txt"),"1 | 00:00:00,000 --> 00:00:02,400\nEN: John bought two apples.\nVI: John đã mua hai quả táo.\n");var imported=OfflineTranslation.Run(cues,new Translator{NoGenerate=true},Path.Combine(root,"paired-cache"),()=>false,(i,m)=>{},pairedSource);Check(imported.Complete&&imported.Text[1]=="John đã mua hai quả táo.","Matching original EN, cue and timecode reuse real provided Vietnamese with semantic verification and no unnecessary generation");var changed=VoiceRenderReport.Snapshot(cues);changed[0].Text="John bought three apples.";var stale=OfflineTranslation.Run(changed,new Translator{NoGenerate=true},Path.Combine(root,"paired-changed-cache"),()=>false,(i,m)=>{},pairedSource);Check(!stale.Complete,"Edited final English cannot reuse a source Vietnamese sentence bound to the old English");bool wrongPrice=false;try{OfflineTranslation.Validate("They priced it at two fifty.","Họ định giá nó 250 đô la.");}catch{wrongPrice=true;}Check(wrongPrice,"A whole 250 dollars cannot pass as a decimal 2.50 price");
  OfflineTranslation.Validate("The judges needed both hands just to hold each bite.","Các giám khảo phải dùng cả hai tay mới giữ được miếng bánh.");bool wrongBoth=false;try{OfflineTranslation.Validate("The judges needed both hands.","Các giám khảo cần ba tay.");}catch{wrongBoth=true;}Check(wrongBoth,"Implicit cardinal both matches Vietnamese hai, but cannot silently become three");
  OfflineTranslation.Validate("The price was $2.50.","Giá là 2,50 đô la.");OfflineTranslation.Validate("He paid 2,500 dollars.","Anh ấy trả 2.500 đô la.");OfflineTranslation.Validate("The price was two fifty.","Giá là 2,50 đô la.");bool decimalPrice=false;try{OfflineTranslation.Validate("The price was $2.50.","Giá là 250 đô la.");}catch{decimalPrice=true;}Check(decimalPrice,"Locale-aware decimal money stays distinct from integer money and preserves thousands grouping");
  bool rejects=false;try{OfflineTranslation.Validate("He paid twelve thousand dollars.","Anh ấy trả ba trăm năm mươi đô la.");}catch{rejects=true;}Check(rejects,"Translation cannot silently alter numeric value");
  Console.WriteLine("TOTAL SYNC216 "+n+" PASS; synthetic voice/translator + real FFmpeg; content examples are explicit test data.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
